SELECT YEAR(opened_date) opened_year, region, QUARTER(opened_date) opened_quarter, SUM(CASE WHEN city = 'New York' THEN 1 ELSE 0 END) new_york_count, ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_singapore, SUM(CASE WHEN city = 'Bangkok' THEN 1 ELSE 0 END) bangkok_count FROM stores WHERE NOT (MONTH(opened_date) IN (2, 3, 12) OR city NOT IN ('New York', 'Tokyo', 'Bangkok')) GROUP BY YEAR(opened_date), region, QUARTER(opened_date) HAVING ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) < 77;
